"""Align masked Excel attributes to TRAIN input-carrier direction, never to inputs."""
from pathlib import Path
import collections
import numpy as np
from weld_pipeline.sjg_local_runtime_904 import read,write,digest
BASE=Path(__file__).resolve().parents[1]/'server_rebuild/expansion_v1';OUT=BASE/'query_endpoint_attribute_supervision_v1';SWAP=np.array([1,0,3,2,5,4,7,6])
def main():
 OUT.mkdir(exist_ok=False);keys=read(BASE/'bounded_raw_training_inputs_v1/protocol.json')['keys'];write(OUT/'protocol.json',dict(keys=keys,source_fields=read(BASE/'endpoint_attribute_supervision_v1/protocol.json')['fields'],output_orientation='Input carrier increasing distance; swap all four endpoint field pairs when reference direction reverses',unique_owner_only=True,multiple_owner_queries_all_masked=True,no_parent_attribute_broadcast=True,unknown_not_zero=True,reference_owner_ids_are_training_labels_not_runtime_features=True,scope='Conditional TRAIN positive-query supervision only; no attribute model fit, actual predictions or frames',DEV_reads=0))
 rows=[]
 for key in keys:
  attr=BASE/'endpoint_attribute_supervision_v1'/key;ar=read(attr/'receipt.json');assert digest(attr/'records.json')==ar['records_sha256'] and digest(attr/'labels.npz')==ar['labels_sha256'];records=read(attr/'records.json');lookup={r['child_id']:i for i,r in enumerate(records)};assert len(lookup)==len(records);z=np.load(attr/'labels.npz');labels={k:z[k] for k in z.files};truthpath=BASE/'labels'/key/'targets.json';truth=read(truthpath);query=BASE/'exhaustive_carrier_supervision_v1/positive_query'/key;qr=read(query/'receipt.json');assert digest(truthpath)==qr['target_sha256'];assert digest(query/'records.json')==qr['files']['records.json'];qrecords=read(query/'records.json');source=BASE/'frozen_features/legacy_runtime'/('source_'+key)/'run185'/('source_'+key);fr=read(source/'input_freeze.json');assert digest(source/'profiles.json')==fr['files']['profiles.json'];profiles=read(source/'profiles.json');N=len(qrecords);state=np.full((N,8),-1,np.int8);value=np.full((N,8),np.nan,np.float64);required=np.zeros((N,8),bool);sm=required.copy();nm=required.copy();valid=np.zeros(N,bool);reversed_rows=np.zeros(N,bool);query_ids=np.zeros(N,np.int64);counts=collections.Counter();owner_weights=np.zeros(N,np.float64);owners=[]
  for i,r in enumerate(qrecords):
   query_ids[i]=r['feature_rows'][0]//2*4+r['query_index']
   if len(r['owners'])!=1:counts['ambiguous_owner_rows']+=1;owners.append(None);continue
   pi,ci=r['owners'][0];child=truth['parents'][pi]['children'][ci];cid=child['original_child_id'];j=lookup[cid];assert records[j]['parent_id']==truth['parents'][pi]['original_parent_id'];assert records[j]['child_index']==child['original_segment_index'];assert records[j]['weld_type']==child['weld_type'];carrier=profiles[r['profile']]['representation'];ref=child['representation']
   if carrier['kind']!='line' or ref['kind']!='line':counts['non_line_rows_masked']+=1;owners.append(None);continue
   d=np.diff(np.asarray(carrier['endpoints_mm']),axis=0)[0];t=np.diff(np.asarray(ref['endpoints_mm']),axis=0)[0];dot=float(d@t);assert abs(dot)>1e-8;order=SWAP if dot<0 else np.arange(8);state[i]=labels['state'][j,order];value[i]=labels['exact_mm'][j,order];required[i]=labels['required_mask'][j,order];sm[i]=labels['state_mask'][j,order];nm[i]=labels['numeric_mask'][j,order];valid[i]=True;reversed_rows[i]=dot<0;owners.append(cid)
   # Exact orientation roundtrip including masks and censored/unknown values.
   inverse=SWAP if dot<0 else np.arange(8);assert np.array_equal(state[i,inverse],labels['state'][j]);assert np.array_equal(value[i,inverse],labels['exact_mm'][j],equal_nan=True);assert np.array_equal(sm[i,inverse],labels['state_mask'][j]);assert np.array_equal(nm[i,inverse],labels['numeric_mask'][j])
  population=collections.Counter(o for o in owners if o is not None)
  for i,o in enumerate(owners):
   if o is not None:owner_weights[i]=1/population[o]/len(population)
  assert np.isfinite(value[nm]).all() and not (nm&~sm).any();assert not sm[~valid].any();dest=OUT/key;dest.mkdir();np.savez(dest/'labels.npz',query_ids=query_ids,state=state,exact_mm=value,required_mask=required,state_mask=sm,numeric_mask=nm,unique_line_owner=valid,reference_reversed=reversed_rows,owner_balanced_weight=owner_weights);receipt=dict(key=key,queries=N,unique_line_owner_queries=int(valid.sum()),reversed_reference_queries=int(reversed_rows.sum()),known_required_states=int(sm.sum()),exact_required_values=int(nm.sum()),represented_children=len(population),excluded_reasons=dict(counts),orientation_roundtrip='PASS',source_attribute_receipt_sha256=digest(attr/'receipt.json'),source_query_receipt_sha256=digest(query/'receipt.json'),target_sha256=digest(truthpath),labels_sha256=digest(dest/'labels.npz'),fit_calls=0,DEV_reads=0);write(dest/'receipt.json',receipt);rows.append(receipt);print(key,receipt['unique_line_owner_queries'],receipt['reversed_reference_queries'],receipt['known_required_states'],flush=True)
 write(OUT/'receipt.json',dict(status='EIGHT_TRAIN_DIRECTION_ALIGNED_ATTRIBUTE_LABELS_READY',cases=rows,fit_calls=0,DEV_reads=0,not_attribute_prediction_or_validation=True))
if __name__=='__main__':main()
